 g(R, 2, 'Mientras ___ (ducharse, yo), sonó el teléfono.', ['me duchaba', 'me estaba duchando', 'estaba duchándome'], 'mientras + action in progress → imperfecto.', 'Me duché y salí.', why=I, sub=IA),
