 c(R, 2, 'Cuando entré en la sala, todos ___.', ['estaban hablando', 'estuvieron hablando', 'hablaron'], 'estaban hablando', 'What was going on when I came in → estaban + gerund.', 'Cuando entré, todos se callaron.', why=I, sub=IA),
